from __future__ import annotations

from typing import Any

from token_validator import extract_role, extract_subject, validate_token


class AuthzService:
    def __init__(self, *, secret: str, issuer: str, audience: str) -> None:
        self._secret = secret
        self._issuer = issuer
        self._audience = audience

    def validate(self, token: str, now_ts: int | None = None) -> dict[str, Any]:
        return validate_token(
            token,
            secret=self._secret,
            issuer=self._issuer,
            audience=self._audience,
            now_ts=now_ts,
        )

    def can_access_admin(self, token: str, now_ts: int | None = None) -> bool:
        validated = self.validate(token, now_ts=now_ts)
        if not validated.get("ok"):
            return False
        role = extract_role(validated)
        return role == "admin"

    def can_access_user(self, token: str, now_ts: int | None = None) -> bool:
        validated = self.validate(token, now_ts=now_ts)
        if not validated.get("ok"):
            return False
        role = extract_role(validated)
        return role in {"user", "admin"}

    def principal(self, token: str, now_ts: int | None = None) -> str:
        validated = self.validate(token, now_ts=now_ts)
        if not validated.get("ok"):
            return ""
        return extract_subject(validated)

    def diagnostics(self, token: str, now_ts: int | None = None) -> dict[str, Any]:
        validated = self.validate(token, now_ts=now_ts)
        if not validated.get("ok"):
            return {
                "ok": False,
                "reason": validated.get("reason", "unknown"),
                "subject": "",
                "role": "",
            }
        return {
            "ok": True,
            "reason": "authorized",
            "subject": extract_subject(validated),
            "role": extract_role(validated),
        }

    def policy_for_path(self, path: str) -> str:
        value = path.strip().lower()
        if value.startswith("/admin"):
            return "admin"
        if value.startswith("/profile") or value.startswith("/orders"):
            return "user"
        return "public"

    def check_path(self, token: str, path: str, now_ts: int | None = None) -> dict[str, Any]:
        policy = self.policy_for_path(path)
        if policy == "public":
            return {"ok": True, "reason": "public"}
        if policy == "admin":
            if self.can_access_admin(token, now_ts=now_ts):
                return {"ok": True, "reason": "admin_allowed", "subject": self.principal(token, now_ts=now_ts)}
            return {"ok": False, "reason": "admin_forbidden"}
        if self.can_access_user(token, now_ts=now_ts):
            return {"ok": True, "reason": "user_allowed", "subject": self.principal(token, now_ts=now_ts)}
        return {"ok": False, "reason": "user_forbidden"}

    def describe(self) -> dict[str, str]:
        return {
            "issuer": self._issuer,
            "audience": self._audience,
            "algorithm": "hs256",
        }

