from __future__ import annotations

import base64
import hashlib
import hmac
import json
from typing import Any


def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("utf-8").rstrip("=")


def _b64url_decode(value: str) -> bytes:
    padding = "=" * ((4 - (len(value) % 4)) % 4)
    return base64.urlsafe_b64decode((value + padding).encode("utf-8"))


def encode_part(value: dict[str, Any]) -> str:
    raw = json.dumps(value, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return _b64url_encode(raw)


def decode_part(value: str) -> dict[str, Any]:
    raw = _b64url_decode(value).decode("utf-8")
    decoded = json.loads(raw)
    if not isinstance(decoded, dict):
        raise ValueError("token part must decode to object")
    return decoded


def signature_for(message: str, secret: str) -> str:
    digest = hmac.new(secret.encode("utf-8"), message.encode("utf-8"), hashlib.sha256).digest()
    return _b64url_encode(digest)


def encode_token(header: dict[str, Any], payload: dict[str, Any], secret: str) -> str:
    header_part = encode_part(header)
    payload_part = encode_part(payload)
    message = f"{header_part}.{payload_part}"
    sig = signature_for(message, secret)
    return f"{message}.{sig}"


def split_token(token: str) -> tuple[str, str, str]:
    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("invalid token format")
    return parts[0], parts[1], parts[2]


def decode_token_without_signature_check(token: str) -> tuple[dict[str, Any], dict[str, Any], str]:
    header_part, payload_part, signature = split_token(token)
    header = decode_part(header_part)
    payload = decode_part(payload_part)
    return header, payload, signature


def rebuild_message(token: str) -> str:
    header_part, payload_part, _signature = split_token(token)
    return f"{header_part}.{payload_part}"


def looks_like_jwt(token: str) -> bool:
    if token.count(".") != 2:
        return False
    for chunk in token.split("."):
        if not chunk.strip():
            return False
    return True


def clone_payload(payload: dict[str, Any]) -> dict[str, Any]:
    return {str(k): v for k, v in payload.items()}


def token_subject(payload: dict[str, Any]) -> str:
    return str(payload.get("sub", "")).strip()


def token_role(payload: dict[str, Any]) -> str:
    return str(payload.get("role", "")).strip().lower()

