from __future__ import annotations

from typing import Any

from authz_service import AuthzService


def _bearer_token(headers: dict[str, Any]) -> str:
    raw = str(headers.get("authorization", "")).strip()
    if not raw:
        return ""
    if not raw.lower().startswith("bearer "):
        return ""
    return raw[7:].strip()


def _path(payload: dict[str, Any]) -> str:
    return str(payload.get("path", "/")).strip() or "/"


def _method(payload: dict[str, Any]) -> str:
    return str(payload.get("method", "GET")).strip().upper() or "GET"


def _request_id(payload: dict[str, Any]) -> str:
    return str(payload.get("request_id", "")).strip() or "req-unknown"


def handle_request(
    payload: dict[str, Any],
    headers: dict[str, Any],
    service: AuthzService,
    *,
    now_ts: int | None = None,
) -> dict[str, Any]:
    path = _path(payload)
    method = _method(payload)
    req_id = _request_id(payload)
    token = _bearer_token(headers)

    if path.startswith("/public"):
        return {"ok": True, "status": 200, "request_id": req_id, "path": path, "method": method}

    if not token:
        return {"ok": False, "status": 401, "reason": "missing_token", "request_id": req_id}

    decision = service.check_path(token, path, now_ts=now_ts)
    if not decision.get("ok"):
        status = 403 if "forbidden" in str(decision.get("reason", "")) else 401
        return {
            "ok": False,
            "status": status,
            "reason": decision.get("reason", "denied"),
            "request_id": req_id,
        }

    return {
        "ok": True,
        "status": 200,
        "reason": decision.get("reason", "allowed"),
        "subject": decision.get("subject", ""),
        "path": path,
        "method": method,
        "request_id": req_id,
    }


def build_headers(token: str) -> dict[str, str]:
    cleaned = token.strip()
    if not cleaned:
        return {}
    return {"authorization": f"Bearer {cleaned}"}


def request_template(path: str, method: str = "GET") -> dict[str, Any]:
    return {"path": path, "method": method, "request_id": f"req-{path.strip('/').replace('/', '-') or 'root'}"}


def handler_diagnostics(path: str, method: str, has_token: bool) -> dict[str, Any]:
    return {
        "path": path.strip(),
        "method": method.strip().upper(),
        "requires_token": not path.strip().lower().startswith("/public"),
        "has_token": bool(has_token),
    }

