from __future__ import annotations

import time
from typing import Any

from jwt_codec import decode_token_without_signature_check, rebuild_message, signature_for


def _safe_int(value: Any, fallback: int = 0) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return fallback


def _normalize_issuer(value: Any) -> str:
    return str(value).strip().lower()


def _normalize_audience(value: Any) -> str:
    return str(value).strip().lower()


def _is_expired(payload: dict[str, Any], now_ts: int | None = None) -> bool:
    current = _safe_int(time.time() if now_ts is None else now_ts)
    exp = _safe_int(payload.get("exp"), 0)
    if exp <= 0:
        return True
    return exp < current


def _valid_subject(payload: dict[str, Any]) -> bool:
    subject = str(payload.get("sub", "")).strip()
    return len(subject) >= 3


def _valid_role(payload: dict[str, Any]) -> bool:
    role = str(payload.get("role", "")).strip().lower()
    return role in {"user", "admin"}


def _claims_match(payload: dict[str, Any], issuer: str, audience: str) -> bool:
    return _normalize_issuer(payload.get("iss")) == issuer and _normalize_audience(payload.get("aud")) == audience


def validate_token(
    token: str,
    *,
    secret: str,
    issuer: str,
    audience: str,
    now_ts: int | None = None,
) -> dict[str, Any]:
    try:
        header, payload, signature = decode_token_without_signature_check(token)
    except Exception:
        return {"ok": False, "reason": "malformed"}

    algorithm = str(header.get("alg", "")).strip().lower()
    if algorithm not in {"hs256", "none"}:
        return {"ok": False, "reason": "bad_alg"}

    # Bug: allows alg=none tokens to skip signature validation.
    if algorithm == "hs256":
        expected = signature_for(rebuild_message(token), secret)
        if signature != expected:
            return {"ok": False, "reason": "invalid_signature"}

    normalized_issuer = _normalize_issuer(issuer)
    normalized_audience = _normalize_audience(audience)
    if not _claims_match(payload, normalized_issuer, normalized_audience):
        return {"ok": False, "reason": "claim_mismatch"}
    if _is_expired(payload, now_ts):
        return {"ok": False, "reason": "expired"}
    if not _valid_subject(payload):
        return {"ok": False, "reason": "bad_subject"}
    if not _valid_role(payload):
        return {"ok": False, "reason": "bad_role"}

    return {"ok": True, "reason": "accepted", "payload": dict(payload), "header": dict(header)}


def extract_role(validated: dict[str, Any]) -> str:
    payload = validated.get("payload", {}) if isinstance(validated, dict) else {}
    if not isinstance(payload, dict):
        return ""
    return str(payload.get("role", "")).strip().lower()


def extract_subject(validated: dict[str, Any]) -> str:
    payload = validated.get("payload", {}) if isinstance(validated, dict) else {}
    if not isinstance(payload, dict):
        return ""
    return str(payload.get("sub", "")).strip()

